<script setup lang="ts">
import { ChatDotRound, Document, Search } from "@element-plus/icons-vue";
import { onMounted, ref } from "vue"; import { api } from "../lib/request";
const kbs=ref<any[]>([]), kb=ref(""), query=ref(""), results=ref<any[]>([]), error=ref(""); onMounted(async()=>{kbs.value=(await api<any>("/api/v1/knowledge-bases")).items;kb.value=kbs.value[0]?.id??""}); async function retrieve(){try{results.value=(await api<any>("/api/v1/retrieve",{method:"POST",body:JSON.stringify({knowledge_base_id:kb.value,query:query.value,top_k:5})})).results}catch(e:any){error.value=e.message}}
</script>
<template>
  <section class="page">
    <div class="page-heading"><div><p class="eyebrow">RETRIEVAL LAB</p><h2>检索调试</h2><p class="page-description">在正式接入前，快速检查知识库能否为问题召回正确上下文。</p></div></div>
    <el-alert v-if="error" :title="error" type="error" class="notice"/>
    <article class="panel query-panel"><div class="panel-body"><div class="query-icon"><Search /></div><div class="query-content"><label class="form-label">选择知识库</label><el-select v-model="kb" placeholder="选择一个知识库"><el-option v-for="item in kbs" :key="item.id" :label="item.name" :value="item.id"/></el-select></div><div class="query-content question"><label class="form-label">测试问题</label><el-input v-model="query" placeholder="例如：产品的退款政策是什么？" @keyup.enter="retrieve"/></div><el-button type="primary" :disabled="!kb || !query" @click="retrieve"><el-icon><Search /></el-icon>开始检索</el-button></div></article>
    <div class="result-heading"><div><h3>召回结果</h3><p>{{ results.length ? `找到 ${results.length} 条相关内容` : '输入问题后，相关文档片段将显示在这里' }}</p></div><span v-if="results.length" class="result-count">TOP {{ results.length }}</span></div>
    <div v-if="results.length" class="results"><article v-for="(result, index) in results" :key="result.chunk_id" class="panel result-card"><div class="result-index">{{ String(index + 1).padStart(2, '0') }}</div><div class="panel-body"><div class="result-meta"><span><el-icon><Document /></el-icon>{{result.filename}}</span><span class="distance">距离 {{result.distance}}</span></div><pre>{{result.content}}</pre></div></article></div>
    <div v-else class="empty-state"><span><ChatDotRound /></span><strong>等待你的问题</strong><p>选择知识库并输入问题，查看系统如何定位关联知识。</p></div>
  </section>
</template>
<style scoped>
