e0eb; border-radius: 16px; background: rgba(255,255,255,.44); }.empty-state > span { display: grid; width: 44px; height: 44px; margin-bottom: 11px; place-items: center; color: #97a4ba; background: #eef2f8; border-radius: 13px; font-size: 21px; }.empty-state strong { color: #5a687d; font-size: 13px; }.empty-state p { margin: 6px 0 0; font-size: 12px; } @media (max-width: 720px) { .query-panel .panel-body { align-items: stretch; flex-wrap: wrap; }.query-icon { display: none; }.query-content, .query-content.question { width: 100%; }.query-panel :deep(.el-button) { width: 100%; } }
